// @zeus-internal
export type MetricFormat = {
    style: "currency" | "percent" | "number";
    decimals?: number;
};
export type KpiMetric = {
    id: string;
    label: string;
    value: number;
    previous: number;
    format?: MetricFormat;
    unit?: string;
    history: number[];
    description: string;
};
export const COMPARISON_LABEL = "over last month";
export const METRICS: KpiMetric[] = [
    {
        id: "revenue",
        label: "Recurring revenue",
        value: 42680,
        previous: 39010,
        format: { style: "currency" },
        history: [46, 58, 50, 68, 94, 61, 65],
        description: "Monthly revenue from active subscriptions, excluding one-time charges.",
    },
    {
        id: "orders",
        label: "Paid accounts",
        value: 1460,
        previous: 1318,
        unit: "teams",
        history: [38, 66, 47, 82, 100, 59, 63],
        description: "Teams with an active paid subscription at the end of the month.",
    },
    {
        id: "customers",
        label: "New trials",
        value: 324,
        previous: 287,
        unit: "this month",
        history: [50, 72, 58, 90, 86, 53, 61],
        description: "Teams that started their first product trial during the month.",
    },
    {
        id: "conversion",
        label: "Trial conversion",
        value: 18.6,
        previous: 17.2,
        format: { style: "percent", decimals: 1 },
        history: [58, 73, 64, 86, 98, 71, 68],
        description: "Completed trials that became paid subscriptions. Changes are shown in percentage points.",
    },
];
export const HIGHLIGHT_INDEX = 4;
const grouped = (value: number, decimals: number) => value.toLocaleString("en-US", { minimumFractionDigits: decimals, maximumFractionDigits: decimals });
export function formatValue(value: number, format: MetricFormat | undefined): string {
    const decimals = format?.decimals ?? 0;
    if (format?.style === "currency")
        return `$${grouped(value, decimals)}`;
    if (format?.style === "percent")
        return `${grouped(value, decimals)}%`;
    return grouped(value, decimals);
}
export function changeParts(metric: KpiMetric): {
    sign: string;
    digits: string;
    suffix: string;
    label: string;
} {
    if (metric.format?.style === "percent") {
        const delta = metric.value - metric.previous;
        const digits = Math.abs(delta).toFixed(2);
        const sign = delta >= 0 ? "+" : "-";
        return { sign, digits, suffix: " pp", label: `${sign}${digits} pp` };
    }
    const delta = ((metric.value - metric.previous) / metric.previous) * 100;
    const digits = Math.abs(delta).toFixed(2);
    const sign = delta >= 0 ? "+" : "-";
    return { sign, digits, suffix: "%", label: `${sign}${digits}%` };
}

