    const initial = firstPaint.current;
    firstPaint.current = false;
    if (!rail.current) return;
    if (!blur || reduced || value === "0" && !blurUpdatesOnly) { rail.current.style.filter = "none"; return; }
    if (blurUpdatesOnly && initial) return;
    const playback = animate(rail.current, { filter: ["blur(10px)", "blur(0px)"] }, { duration: 0.32, delay, ease: ARTEMIS_EASE_OUT });
